{"items":[{"id":"cap-v2-numeric_reasoning-go-generation-01","test_code":"package solution

import (
	"reflect"
	"testing"
)

func cloneMatrix(matrix [][]int64) [][]int64 {
	if matrix == nil {
		return nil
	}
	clone := make([][]int64, len(matrix))
	for i, row := range matrix {
		if row != nil {
			clone[i] = make([]int64, len(row))
			copy(clone[i], row)
		}
	}
	return clone
}

func TestRankRowSumsDescendingAndStable(t *testing.T) {
	matrix := [][]int64{
		{2, 3},
		{10, -1},
		{4, 1},
		{-7, 2},
	}
	want := []int{1, 0, 2, 3}
	if got := RankRowSums(matrix); !reflect.DeepEqual(got, want) {
		t.Fatalf("RankRowSums() = %v, want %v", got, want)
	}
}

func TestRankRowSumsEmptyAndZeroRows(t *testing.T) {
	for _, matrix := range [][][]int64{nil, {}} {
		got := RankRowSums(matrix)
		if len(got) != 0 {
			t.Fatalf("RankRowSums(%v) = %v, want empty result", matrix, got)
		}
	}

	matrix := [][]int64{nil, {}, {1, -1}, {0}, {-1}}
	want := []int{0, 1, 2, 3, 4}
	if got := RankRowSums(matrix); !reflect.DeepEqual(got, want) {
		t.Fatalf("RankRowSums(%v) = %v, want %v", matrix, got, want)
	}
}

func TestRankRowSumsNegativeAndBoundaryValues(t *testing.T) {
	matrix := [][]int64{
		{-9},
		{-2, -3},
		{1<<62 - 1, 1},
		{1<<62 - 2, 2},
		{-1 << 62, -1},
	}
	want := []int{2, 3, 1, 0, 4}
	if got := RankRowSums(matrix); !reflect.DeepEqual(got, want) {
		t.Fatalf("RankRowSums() = %v, want %v", got, want)
	}
}

func TestRankRowSumsDoesNotMutateMatrixAndIsDeterministic(t *testing.T) {
	matrix := [][]int64{{3, -1}, {1, 1}, {}, nil, {8}}
	before := cloneMatrix(matrix)
	want := []int{4, 0, 1, 2, 3}

	first := RankRowSums(matrix)
	second := RankRowSums(matrix)
	if !reflect.DeepEqual(first, want) || !reflect.DeepEqual(second, want) {
		t.Fatalf("repeated results = %v and %v, want %v", first, second, want)
	}
	if !reflect.DeepEqual(matrix, before) {
		t.Fatalf("matrix mutated: got %v, want %v", matrix, before)
	}

	first[0] = -1
	if !reflect.DeepEqual(second, want) {
		t.Fatalf("changing one result affected another: got %v, want %v", second, want)
	}
}
"},{"id":"cap-v2-ordering_and_selection-go-repair-02","test_code":"package solution

import (
	"reflect"
	"testing"
)

func cloneChapters(input []Chapter) []Chapter {
	if input == nil {
		return nil
	}
	out := make([]Chapter, len(input))
	for i, chapter := range input {
		out[i] = chapter
		if chapter.Keywords != nil {
			out[i].Keywords = make([]string, len(chapter.Keywords))
			copy(out[i].Keywords, chapter.Keywords)
		}
	}
	return out
}

func TestOrderChaptersOrderingStabilityAndDeepIndependence(t *testing.T) {
	input := []Chapter{
		{Code: "stable", Section: 2, Importance: 7, Keywords: []string{"first", "shared"}},
		{Code: "later", Section: 3, Importance: 100, Keywords: nil},
		{Code: "stable", Section: 2, Importance: 7, Keywords: []string{"second"}},
		{Code: "important", Section: 2, Importance: 9, Keywords: []string{}},
		{Code: "alpha", Section: 2, Importance: 7, Keywords: []string{"alpha"}},
		{Code: "early", Section: 1, Importance: 0, Keywords: []string{"early"}},
	}
	original := cloneChapters(input)
	want := []Chapter{input[5], input[3], input[4], input[0], input[2], input[1]}

	got := OrderChapters(input)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("OrderChapters() = %#v, want %#v", got, want)
	}
	if !reflect.DeepEqual(input, original) {
		t.Fatalf("OrderChapters mutated input: got %#v, want %#v", input, original)
	}

	got[3].Code = "changed"
	got[3].Section = -100
	got[3].Importance = -100
	got[3].Keywords[0] = "changed"
	if !reflect.DeepEqual(input, original) {
		t.Fatalf("changing result changed input: got %#v, want %#v", input, original)
	}
}

func TestOrderChaptersOrdersNegativeAndDuplicateFields(t *testing.T) {
	input := []Chapter{
		{Code: "b", Section: -1, Importance: -5},
		{Code: "a", Section: -1, Importance: -5},
		{Code: "z", Section: -2, Importance: -100},
		{Code: "c", Section: -1, Importance: 10},
		{Code: "a", Section: -1, Importance: -5},
	}
	want := []Chapter{input[2], input[3], input[1], input[4], input[0]}
	if got := OrderChapters(input); !reflect.DeepEqual(got, want) {
		t.Fatalf("OrderChapters() = %#v, want %#v", got, want)
	}
}

func TestOrderChaptersPreservesNilAndEmptyKeywords(t *testing.T) {
	input := []Chapter{
		{Code: "nil", Keywords: nil},
		{Code: "empty", Keywords: []string{}},
	}
	got := OrderChapters(input)

	var nilChapter, emptyChapter *Chapter
	for i := range got {
		switch got[i].Code {
		case "nil":
			nilChapter = &got[i]
		case "empty":
			emptyChapter = &got[i]
		}
	}
	if nilChapter == nil || nilChapter.Keywords != nil {
		t.Fatalf("nil Keywords was not preserved: %#v", nilChapter)
	}
	if emptyChapter == nil || emptyChapter.Keywords == nil || len(emptyChapter.Keywords) != 0 {
		t.Fatalf("non-nil empty Keywords was not preserved: %#v", emptyChapter)
	}
}

func TestOrderChaptersEmptyIsNonNil(t *testing.T) {
	for _, input := range [][]Chapter{nil, {}} {
		got := OrderChapters(input)
		if got == nil {
			t.Fatal("OrderChapters returned nil for empty input")
		}
		if len(got) != 0 {
			t.Fatalf("OrderChapters returned %d chapters, want zero", len(got))
		}
	}
}
"}]}

