{"items":[{"id":"cap-v2-string_and_unicode-go-generation-02","problem":"Implement one complete Go source file using `package solution` and this exact public API:

```go
type LetterCount struct {
    Letter rune
    Count  int
}

func RankLetters(text string) []LetterCount
```

Iterate over the Unicode code points in `text`. Ignore every code point for which `unicode.IsLetter` is false. Convert each retained letter with `unicode.ToLower`, then count occurrences of the resulting rune.

Return one `LetterCount` per distinct lowercase letter, ranked by decreasing `Count`. Letters with equal counts must remain in the order in which their lowercase forms first appeared in `text`. The result for input containing no letters must be a non-nil empty slice.

Use only the Go standard library. Do not access the filesystem, network, clock, or randomness.","reference_code":"package solution

import (
    "sort"
    "unicode"
)

type LetterCount struct {
    Letter rune
    Count  int
}

func RankLetters(text string) []LetterCount {
    counts := make(map[rune]int)
    order := make([]rune, 0)

    for _, r := range text {
        if !unicode.IsLetter(r) {
            continue
        }
        folded := unicode.ToLower(r)
        if _, exists := counts[folded]; !exists {
            order = append(order, folded)
        }
        counts[folded]++
    }

    result := make([]LetterCount, 0, len(order))
    for _, r := range order {
        result = append(result, LetterCount{Letter: r, Count: counts[r]})
    }

    sort.SliceStable(result, func(i, j int) bool {
        return result[i].Count > result[j].Count
    })
    return result
}
","known_bad_code":"package solution

import (
    "sort"
    "unicode"
)

type LetterCount struct {
    Letter rune
    Count  int
}

func RankLetters(text string) []LetterCount {
    counts := make(map[rune]int)
    for _, r := range text {
        if unicode.IsLetter(r) {
            counts[unicode.ToLower(r)]++
        }
    }

    result := make([]LetterCount, 0, len(counts))
    for r, count := range counts {
        result = append(result, LetterCount{Letter: r, Count: count})
    }
    sort.Slice(result, func(i, j int) bool {
        return result[i].Count > result[j].Count
    })
    return result
}
","known_bad_label":"Builds tied entries from randomized map iteration, so equal-frequency letters do not retain first-appearance order."}]}

