{"items":[{"id":"cap-v2-associative_aggregation-java-generation-02","test_code":"import java.util.LinkedHashMap;
import java.util.Map;

public class SolutionTest {
    public static void main(String[] args) {
        assertMapEquals(mapOf(), Solution.sumAcceptedUnits(null), "null input");
        assertMapEquals(mapOf(), Solution.sumAcceptedUnits(new String[0]), "empty input");

        String[] normal = {
            "ITEM1|LOC1|12",
            "ITEM2|LOC2|8",
            "A9|LOC1|30",
            "Z|LOC2|2",
            "X1|WAREHOUSE9|100000"
        };
        assertMapEquals(mapOf(
            "LOC1", 42,
            "LOC2", 10,
            "WAREHOUSE9", 100000
        ), Solution.sumAcceptedUnits(normal), "normal aggregation");

        String[] boundariesAndMalformed = {
            "A|L|1",
            "B2|L|100000",
            null,
            "",
            "A|L",
            "A|L|2|EXTRA",
            "|L|5",
            "A||5",
            "a|L|5",
            "A|loc|5",
            "A-B|L|5",
            "A|L_1|5",
            " A|L|5",
            "A|L |5",
            "A|L|0",
            "A|L|100001",
            "A|L|-1",
            "A|L|1.0",
            "A|L|+1",
            "A|L| 1",
            "A|L|1 ",
            "A|L|2147483648",
            "A|L|",
            "A1|L2|00003"
        };
        assertMapEquals(mapOf("L", 100002, "L2", 3),
            Solution.sumAcceptedUnits(boundariesAndMalformed),
            "boundaries, malformed lines, and exact code rules");

        String[] input = {"P1|NORTH|7", "P2|NORTH|11", "P3|SOUTH|1"};
        String[] snapshot = input.clone();
        Map<String, Integer> first = Solution.sumAcceptedUnits(input);
        assertArrayEquals(snapshot, input, "input must not be modified");
        assertMapEquals(mapOf("NORTH", 18, "SOUTH", 1), first, "repeatable result");

        first.put("NORTH", -1);
        first.put("EXTRA", 99);
        assertMapEquals(mapOf("NORTH", 18, "SOUTH", 1), Solution.sumAcceptedUnits(input),
            "later calls must be independent of a prior returned map");
    }

    private static Map<String, Integer> mapOf(Object... entries) {
        Map<String, Integer> map = new LinkedHashMap<>();
        for (int i = 0; i < entries.length; i += 2) {
            map.put((String) entries[i], (Integer) entries[i + 1]);
        }
        return map;
    }

    private static void assertMapEquals(Map<String, Integer> expected,
                                        Map<String, Integer> actual,
                                        String message) {
        if (actual == null || !expected.equals(actual)) {
            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
        }
    }

    private static void assertArrayEquals(String[] expected, String[] actual, String message) {
        if (expected.length != actual.length) {
            throw new AssertionError(message + ": array length changed");
        }
        for (int i = 0; i < expected.length; i++) {
            if (expected[i] == null ? actual[i] != null : !expected[i].equals(actual[i])) {
                throw new AssertionError(message + ": difference at index " + i);
            }
        }
    }
}
"},{"id":"cap-v2-binary_and_bitwise-java-repair-01","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testEmptyOperations();
        testSeparatedDuplicateIsIgnored();
        testSetAndClearAreDistinctOperations();
        testAllBitPositions();
        testSignBit();
        testInputIsNotMutated();
        testStableIndependentInvocations();
    }

    private static void testEmptyOperations() {
        assertEquals(0x13579BDF, Solution.applyUniqueOperations(0x13579BDF, new int[0]), "empty operations");
    }

    private static void testSeparatedDuplicateIsIgnored() {
        int result = Solution.applyUniqueOperations(0, new int[] {33, 1, 33});
        assertEquals(0, result, "non-adjacent duplicate set operation must be ignored");

        result = Solution.applyUniqueOperations(-1, new int[] {5, 37, 5});
        assertEquals(-1, result, "non-adjacent duplicate clear operation must be ignored");
    }

    private static void testSetAndClearAreDistinctOperations() {
        int result = Solution.applyUniqueOperations(0, new int[] {32, 0, 32, 0});
        assertEquals(0, result, "encoded set and clear operations must each run once");

        result = Solution.applyUniqueOperations(0, new int[] {35, 35, 3, 35, 3});
        assertEquals(0, result, "adjacent and separated duplicates");
    }

    private static void testAllBitPositions() {
        int[] clearThenSet = new int[64];
        for (int i = 0; i < 64; i++) {
            clearThenSet[i] = i;
        }
        assertEquals(-1, Solution.applyUniqueOperations(0, clearThenSet), "all clear operations followed by all set operations");

        int[] setThenClear = new int[64];
        for (int i = 0; i < 32; i++) {
            setThenClear[i] = 63 - i;
            setThenClear[32 + i] = 31 - i;
        }
        assertEquals(0, Solution.applyUniqueOperations(-1, setThenClear), "all set operations followed by all clear operations");
    }

    private static void testSignBit() {
        assertEquals(Integer.MIN_VALUE, Solution.applyUniqueOperations(0, new int[] {63}), "set bit 31");
        assertEquals(0, Solution.applyUniqueOperations(Integer.MIN_VALUE, new int[] {31}), "clear bit 31");
    }

    private static void testInputIsNotMutated() {
        int[] operations = {34, 7, 34, 39, 2};
        int[] original = operations.clone();
        Solution.applyUniqueOperations(123, operations);
        assertTrue(Arrays.equals(original, operations), "operations array was mutated");
    }

    private static void testStableIndependentInvocations() {
        int[] operations = {33, 1, 33};
        assertEquals(0, Solution.applyUniqueOperations(0, operations), "first invocation");
        assertEquals(0, Solution.applyUniqueOperations(0, operations), "repeated invocation");
        assertEquals(2, Solution.applyUniqueOperations(2, new int[0]), "state leaked between invocations");
    }

    private static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) {
            throw new AssertionError(message + ": expected " + expected + " but was " + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}
"},{"id":"cap-v2-numeric_reasoning-java-generation-01","test_code":"import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        testDistinctValuesAndDuplicates();
        testZeroLimitAndEmptyInput();
        testLongAccumulation();
        testNonMutationAndRepeatedCalls();
    }

    private static void testDistinctValuesAndDuplicates() {
        assertEquals(23L,
                Solution.totalUniqueCredits(new int[]{12, 4, 12, 9}, 10),
                "duplicate values must contribute once");
        assertEquals(12L,
                Solution.totalUniqueCredits(new int[]{3, 3, 4, 5, 4}, 100),
                "limit above every value");
    }

    private static void testZeroLimitAndEmptyInput() {
        assertEquals(0L,
                Solution.totalUniqueCredits(new int[]{0, 1, Integer.MAX_VALUE, 1}, 0),
                "zero per-value limit");
        assertEquals(0L,
