import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

public class SolutionTest {
    public static void main(String[] args) {
        Locale originalLocale = Locale.getDefault();
        try {
            Locale.setDefault(new Locale("tr", "TR"));
            testNormalizationTrimmingDeduplicationAndOrder();
            testCodePointBoundary();
            testEmptyRegistrationSet();
            testInvalidNamesAndQuery();
        } finally {
            Locale.setDefault(originalLocale);
        }
    }

    private static void testNormalizationTrimmingDeduplicationAndOrder() {
        List<String> proposed = new ArrayList<String>(Arrays.asList(
                "\u00A0Alpha\u2003",
                "Cafe\u0301",
                "CAFÉ",
                "beta",
                "GAMMA",
                "gamma"));
        List<String> snapshot = new ArrayList<String>(proposed);

        assertListEquals(Arrays.asList("Alpha", "Café", "beta", "GAMMA"),
                Solution.registerAndFind(proposed, "\u2003A\u00A0"));
        assertListEquals(Collections.singletonList("Café"),
                Solution.registerAndFind(proposed, "FE\u0301"));
        assertListEquals(Collections.singletonList("Alpha"),
                Solution.registerAndFind(proposed, "ALP"));
        assertListEquals(Collections.<String>emptyList(),
                Solution.registerAndFind(proposed, "zzz"));
        assertListEquals(snapshot, proposed);
    }

    private static void testCodePointBoundary() {
        String emoji = "\uD83D\uDE00";
        StringBuilder twenty = new StringBuilder();
        for (int i = 0; i < 20; i++) {
            twenty.append(emoji);
        }
        assertListEquals(Collections.singletonList(twenty.toString()),
                Solution.registerAndFind(Collections.singletonList(twenty.toString()), emoji));

        final StringBuilder twentyOne = new StringBuilder(twenty);
        twentyOne.append(emoji);
        expectIllegalArgument(new ThrowingAction() {
            public void run() {
                Solution.registerAndFind(Collections.singletonList(twentyOne.toString()), "x");
            }
        });
    }

    private static void testEmptyRegistrationSet() {
        assertListEquals(Collections.<String>emptyList(),
                Solution.registerAndFind(Collections.<String>emptyList(), "valid"));
    }

    private static void testInvalidNamesAndQuery() {
        expectIllegalArgument(new ThrowingAction() {
            public void run() {
                Solution.registerAndFind(Collections.singletonList("\t\u00A0\u2003"), "x");
            }
        });
        expectIllegalArgument(new ThrowingAction() {
            public void run() {
                Solution.registerAndFind(Collections.singletonList("abcdefghijklmnopqrstu"), "x");
            }
        });
        expectIllegalArgument(new ThrowingAction() {
            public void run() {
                Solution.registerAndFind(Collections.singletonList("valid"), "\n\u00A0\u2003");
            }
        });
    }

    private interface ThrowingAction {
        void run();
    }

    private static void expectIllegalArgument(ThrowingAction action) {
        try {
            action.run();
            throw new AssertionError("Expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
            // Expected.
        }
    }

    private static void assertListEquals(List<String> expected, List<String> actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected " + expected + " but got " + actual);
        }
    }
}
