public final class Solution {
    private Solution() {
    }

    public static int applyUniqueOperations(int initialMask, int[] operations) {
        int result = initialMask;
        int previous = -1;

        for (int operation : operations) {
            if (operation == previous) {
                continue;
            }
            previous = operation;

            int bit = operation & 31;
