The current implementation counts duplicate voters:

```javascript
function compareText(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

function rankChoices(ballots) {
  const counts = new Map();

  for (const ballot of ballots) {
    counts.set(ballot.choice, (counts.get(ballot.choice) || 0) + 1);
  }

  return Array.from(counts, ([choice, count]) => ({ choice, count }))
    .sort((a, b) => {
      if (a.count !== b.count) return b.count - a.count;
      return compareText(a.choice, b.choice);
    });
}

module.exports = { rankChoices };
```

