{"items":[{"id":"cap-v2-binary_and_bitwise-python-generation-01","test_code":"import copy
import unittest

import solution


class EncodeFlagUpdatesTests(unittest.TestCase):
    def test_combines_duplicate_masks_with_bitwise_or(self):
        updates = [(2, 0b00000101), (2, 0b00011000), (9, 0b10000000)]
        self.assertEqual(
            solution.encode_flag_updates(updates),
            bytes([2, 2, 0b00011101, 9, 0b10000000, 148]),
        )

    def test_empty_input_has_count_and_checksum(self):
        result = solution.encode_flag_updates([])
        self.assertIs(type(result), bytes)
        self.assertEqual(result, b"\x00\x00")

    def test_repeated_bits_do_not_cancel_or_increment(self):
        updates = [(7, 5), (7, 5), (7, 1)]
        self.assertEqual(solution.encode_flag_updates(updates), bytes([1, 7, 5, 3]))

    def test_zero_and_byte_boundaries(self):
        updates = [(0, 0), (0, 255), (255, 0)]
        self.assertEqual(
            solution.encode_flag_updates(updates),
            bytes([2, 0, 255, 255, 0, 2]),
        )

    def test_all_255_distinct_slots(self):
        updates = [(slot, slot) for slot in range(255)]
        result = solution.encode_flag_updates(updates)

        expected_prefix = bytearray([255])
        for slot in range(255):
            expected_prefix.extend((slot, slot))

        checksum = 0
        for value in expected_prefix:
            checksum ^= value

        expected = bytes(expected_prefix + bytearray([checksum]))
        self.assertEqual(result, expected)
        self.assertEqual(len(result), 512)
        self.assertEqual(result[0], 255)
        self.assertEqual(result[-1], 255)

    def test_preserves_distinct_slot_order(self):
        updates = [(3, 1), (3, 2), (8, 4), (10, 8), (10, 16)]
        self.assertEqual(
            solution.encode_flag_updates(updates),
            bytes([3, 3, 3, 8, 4, 10, 24, 29]),
        )

    def test_input_is_not_modified_and_output_is_stable(self):
        updates = [(1, 2), (1, 4), (200, 128)]
        original = copy.deepcopy(updates)

        first = solution.encode_flag_updates(updates)
        second = solution.encode_flag_updates(updates)

        self.assertEqual(updates, original)
        self.assertEqual(first, second)
        self.assertIs(type(first), bytes)


if __name__ == "__main__":
    unittest.main()
"},{"id":"cap-v2-binary_and_bitwise-python-generation-02","test_code":"import unittest

from solution import encode_flag_table


class EncodeFlagTableTests(unittest.TestCase):
    def test_empty_input_is_checksum_only(self):
        result = encode_flag_table([])
        self.assertEqual(result, b"\x00")
        self.assertIs(type(result), bytes)

    def test_single_record_encoding_and_checksum(self):
        result = encode_flag_table([(3, 0xABC)])
        self.assertEqual(result, bytes([0x3A, 0xBC, 0x86]))

    def test_duplicates_are_ored_and_channels_are_sorted(self):
        entries = [
            (15, 0x001),
            (0, 0xFFF),
            (7, 0x100),
            (0, 0x001),
            (7, 0x00F),
            (15, 0x800),
        ]
        expected = bytes([0x0F, 0xFF, 0x71, 0x0F, 0xF8, 0x01, 0x77])
        self.assertEqual(encode_flag_table(entries), expected)

    def test_boundary_channels_and_masks(self):
        result = encode_flag_table([(15, 4095), (0, 0)])
        self.assertEqual(result, bytes([0x00, 0x00, 0xFF, 0xFF, 0x00]))

    def test_repeated_duplicate_bits_do_not_change_mask(self):
        result = encode_flag_table([(4, 0x555), (4, 0x555), (4, 0x0AA)])
        self.assertEqual(result, bytes([0x45, 0xFF, 0xBA]))

    def test_input_is_not_mutated_and_result_is_deterministic(self):
        entries = [(9, 0x123), (2, 0x456), (9, 0x800)]
        snapshot = list(entries)

        first = encode_flag_table(entries)
        second = encode_flag_table(entries)

        self.assertEqual(entries, snapshot)
        self.assertEqual(first, second)
        self.assertEqual(first, bytes([0x24, 0x56, 0x99, 0x23, 0xC8]))
        self.assertIs(type(first), bytes)


if __name__ == "__main__":
    unittest.main()
"},{"id":"cap-v2-graph_and_tree-python-generation-01","test_code":"import unittest

from solution import dependency_walks


class DependencyWalksTests(unittest.TestCase):
    def test_depth_first_preorder_and_neighbor_order(self):
        graph = {
            "app": ["db", "api"],
            "db": ["disk", "shared"],
            "api": ["shared", "auth"],
            "auth": [],
        }
        self.assertEqual(
            dependency_walks(graph, ["app"]),
            {"app": ("app", "db", "disk", "shared", "api", "auth")},
        )

    def test_cycle_and_repeated_references_visit_each_node_once(self):
        graph = {
            "a": ["b", "b", "c"],
            "b": ["c", "a"],
            "c": ["a"],
        }
        self.assertEqual(
            dependency_walks(graph, ["a"]),
            {"a": ("a", "b", "c")},
        )

    def test_missing_nodes_are_leaves(self):
        graph = {
            "root": ["missing", "known"],
            "known": ["other-missing"],
        }
        self.assertEqual(
            dependency_walks(graph, ["root", "missing"]),
            {
                "root": ("root", "missing", "known", "other-missing"),
                "missing": ("missing",),
            },
        )

    def test_each_root_has_fresh_visited_state(self):
        graph = {
            "left": ["shared"],
            "right": ["shared"],
            "shared": ["leaf"],
        }
        self.assertEqual(
            dependency_walks(graph, ["left", "right"]),
            {
                "left": ("left", "shared", "leaf"),
                "right": ("right", "shared", "leaf"),
            },
        )

    def test_no_state_persists_between_calls(self):
        graph = {"a": ["b"], "b": []}
        self.assertEqual(dependency_walks(graph, ["a"]), {"a": ("a", "b")})
        self.assertEqual(
            dependency_walks(graph, ["b", "a"]),
            {"b": ("b",), "a": ("a", "b")},
        )

    def test_empty_roots_returns_empty_dictionary(self):
        self.assertEqual(dependency_walks({"a": ["b"]}, []), {})

    def test_supports_one_shot_root_and_neighbor_iterables(self):
        graph = {
            "left": (node for node in ["shared"]),
            "right": (node for node in ["shared"]),
            "shared": (node for node in ["leaf"]),
        }
        roots = (root for root in ["left", "right"])
        self.assertEqual(
            dependency_walks(graph, roots),
            {
                "left": ("left", "shared", "leaf"),
                "right": ("right", "shared", "leaf"),
            },
        )

    def test_does_not_mutate_reusable_inputs(self):
        graph = {"a": ["b", "c"], "b": ["c"], "c": []}
        roots = ["a", "b"]
        original_graph = {key: list(value) for key, value in graph.items()}
        original_roots = list(roots)

        dependency_walks(graph, roots)

        self.assertEqual(graph, original_graph)
        self.assertEqual(roots, original_roots)


if __name__ == "__main__":
    unittest.main()
"},{"id":"cap-v2-numeric_reasoning-python-repair-01","test_code":"import unittest

from solution import largest_proper_factor


class LargestProperFactorTests(unittest.TestCase):
    def test_composite_numbers(self):
        self.assertEqual(largest_proper_factor(12), 6)
        self.assertEqual(largest_proper_factor(49), 7)
        self.assertEqual(largest_proper_factor(100), 50)

    def test_prime_numbers_have_one_as_largest_proper_factor(self):
        self.assertEqual(largest_proper_factor(2), 1)
        self.assertEqual(largest_proper_factor(97), 1)

    def test_integers_at_or_below_one_return_none(self):
        for value in (1, 0, -1, -100):
            with self.subTest(value=value):
                self.assertIsNone(largest_proper_factor(value))

    def test_booleans_are_rejected(self):
        self.assertIsNone(largest_proper_factor(True))
        self.assertIsNone(largest_proper_factor(False))

    def test_non_integer_values_return_none_without_raising(self):
        malformed_values = [None, "12", 12.0, 3.5, [], {}, object()]
        for value in malformed_values:
            with self.subTest(type=type(value).__name__):
                self.assertIsNone(largest_proper_factor(value))

    def test_integer_subclass_is_still_an_integer(self):
        class CustomInt(int):
            pass

        self.assertEqual(largest_proper_factor(CustomInt(15)), 5)


if __name__ == "__main__":
    unittest.main()
"},{"id":"cap-v2-stateful_workflows-python-repair-01","test_code":"import unittest

from solution import replay_workflows


class ReplayWorkflowsTests(unittest.TestCase):
    def test_normal_transitions_for_multiple_workflows(self):
        initial = {"a": "new", "b": "active", "c": "complete"}
        events = [
            ("e1", "a", "start"),
            ("e2", "b", "finish"),
            ("e3", "a", "finish"),
        ]
        self.assertEqual(
            replay_workflows(initial, events),
            {"a": "complete", "b": "complete", "c": "complete"},
        )

    def test_empty_inputs_and_no_events(self):
        self.assertEqual(replay_workflows({}, []), {})

        initial = {"a": "new"}
        result = replay_workflows(initial, ())
        self.assertEqual(result, initial)
        self.assertIsNot(result, initial)

    def test_duplicate_is_ignored_before_workflow_or_action_inspection(self):
        initial = {"a": "new"}
        events = [
            ("same", "a", "start"),
            ("same", "missing", "not-an-action"),
            ("finish", "a", "finish"),
        ]
        self.assertEqual(replay_workflows(initial, events), {"a": "complete"})

    def test_duplicate_does_not_apply_transition_twice(self):
        initial = {"a": "new", "b": "new"}
        events = [
            (1, "a", "start"),
            (1, "b", "start"),
        ]
        self.assertEqual(
            replay_workflows(initial, events),
            {"a": "active", "b": "new"},
        )

    def test_event_ids_are_global_across_workflows(self):
        initial = {"left": "new", "right": "active"}
        events = [
            ("event", "left", "start"),
            ("event", "right", "finish"),
        ]
        self.assertEqual(
            replay_workflows(initial, events),
            {"left": "active", "right": "active"},
        )

    def test_invalid_unique_transitions_raise_value_error(self):
        cases = [
            ({"a": "active"}, [(1, "a", "start")]),
            ({"a": "new"}, [(1, "a", "finish")]),
            ({"a": "complete"}, [(1, "a", "finish")]),
            ({"a": "new"}, [(1, "a", "unknown")]),
            ({"a": "new"}, [(1, "missing", "start")]),
        ]
        for initial, events in cases:
            with self.subTest(initial=initial, events=events):
                with self.assertRaises(ValueError):
                    replay_workflows(initial, events)

    def test_initial_mapping_is_never_mutated_on_success_or_failure(self):
        initial = {"a": "new", "b": "active"}
        before = dict(initial)

        result = replay_workflows(initial, [(1, "a", "start")])
        self.assertEqual(initial, before)
        self.assertIsNot(result, initial)

        with self.assertRaises(ValueError):
            replay_workflows(initial, [(1, "a", "start"), (2, "a", "start")])
        self.assertEqual(initial, before)


if __name__ == "__main__":
    unittest.main()
