mod solution;

use solution::DigitStrideFinder;

#[test]
fn finds_all_stride_two_numbers_in_increasing_order() {
    let mut finder = DigitStrideFinder::new();
    assert_eq!(
        finder.find(0, u32::MAX),
        vec![
            13, 24, 35, 46, 57, 68, 79, 135, 246, 357, 468, 579, 1357, 2468,
            3579,
        ]
    );
}

#[test]
fn range_bounds_are_inclusive() {
    let mut finder = DigitStrideFinder::new();
    assert_eq!(finder.find(24, 35), vec![24, 35]);
    assert_eq!(finder.find(1357, 1357), vec![1357]);
}

#[test]
fn excludes_single_digits_and_nonmatching_numbers() {
    let mut finder = DigitStrideFinder::new();
    assert_eq!(finder.find(0, 12), Vec::<u32>::new());
    assert_eq!(finder.find(80, 134), Vec::<u32>::new());
    assert_eq!(finder.find(2458, 2458), Vec::<u32>::new());
}

#[test]
fn each_find_call_discards_previous_matches() {
    let mut finder = DigitStrideFinder::new();

    assert_eq!(finder.find(13, 79), vec![13, 24, 35, 46, 57, 68, 79]);
    assert_eq!(finder.find(2468, 2468), vec![2468]);
    assert_eq!(finder.find(100_000, u32::MAX), Vec::<u32>::new());
    assert_eq!(finder.find(35, 57), vec![35, 46, 57]);
}

#[test]
fn supports_smallest_and_largest_input_boundaries() {
    let mut finder = DigitStrideFinder::new();
    assert_eq!(finder.find(0, 0), Vec::<u32>::new());
    assert_eq!(finder.find(u32::MAX, u32::MAX), Vec::<u32>::new());
}

#[test]
fn returns_only_numbers_whose_adjacent_digits_increase_by_two() {
    let mut finder = DigitStrideFinder::new();
    assert_eq!(finder.find(130, 580), vec![135, 246, 357, 468, 579]);
}
"},{"id":"cap-v2-ordering_and_selection-rust-repair-01","test_code":"#[path = "solution.rs"]
mod solution;

use solution::{rank_tasks, Task};

fn task(id: &str, priority: i32, deadline: u32) -> Task {
    Task {
        id: id.to_string(),
        priority,
        deadline,
    }
}

#[test]
fn ranks_by_priority_deadline_and_id() {
    let mut tasks = vec![
        task("zeta", 5, 2),
        task("beta", 7, 9),
        task("omega", 7, 1),
        task("alpha", 7, 1),
        task("low", -2, 0),
    ];

    assert_eq!(
        rank_tasks(&mut tasks),
        vec![
            task("alpha", 7, 1),
            task("omega", 7, 1),
            task("beta", 7, 9),
            task("zeta", 5, 2),
            task("low", -2, 0),
        ]
    );
}

#[test]
fn returns_independent_clones_and_leaves_input_unchanged() {
    let mut tasks = vec![
        task("last", 1, 9),
        task("first", 10, 1),
        task("middle", 5, 4),
    ];
    let original = tasks.clone();
    let task_addresses: Vec<*const Task> = tasks.iter().map(|item| item as *const Task).collect();
    let id_addresses: Vec<*const u8> = tasks.iter().map(|item| item.id.as_ptr()).collect();

    let ranked = rank_tasks(&mut tasks);

    assert_eq!(tasks, original);
    assert_eq!(
        tasks.iter().map(|item| item as *const Task).collect::<Vec<_>>(),
        task_addresses
    );
    assert_eq!(
        tasks.iter().map(|item| item.id.as_ptr()).collect::<Vec<_>>(),
        id_addresses
    );
    assert_eq!(
        ranked,
        vec![
            task("first", 10, 1),
            task("middle", 5, 4),
            task("last", 1, 9),
        ]
    );
    assert!(ranked
        .iter()
        .all(|copy| id_addresses.iter().all(|&address| copy.id.as_ptr() != address)));
}

#[test]
fn accepts_empty_and_single_element_slices() {
    let mut empty: Vec<Task> = Vec::new();
    assert!(rank_tasks(&mut empty).is_empty());

    let mut one = vec![task("only", 3, 8)];
    let original = one.clone();
    let original_id_address = one[0].id.as_ptr();
    let ranked = rank_tasks(&mut one);

    assert_eq!(ranked, original);
    assert_eq!(one, original);
    assert_eq!(one[0].id.as_ptr(), original_id_address);
    assert_ne!(ranked[0].id.as_ptr(), original_id_address);
}

#[test]
fn handles_numeric_boundaries_without_overflow() {
    let mut tasks = vec![
        task("minimum", i32::MIN, u32::MAX),
        task("maximum-late", i32::MAX, u32::MAX),
        task("maximum-early", i32::MAX, 0),
    ];
    let original = tasks.clone();

    assert_eq!(
        rank_tasks(&mut tasks),
        vec![
            task("maximum-early", i32::MAX, 0),
            task("maximum-late", i32::MAX, u32::MAX),
            task("minimum", i32::MIN, u32::MAX),
        ]
    );
    assert_eq!(tasks, original);
}

#[test]
fn preserves_multiplicity_for_tasks_equal_on_all_keys() {
    let mut tasks = vec![
        task("same", 4, 6),
        task("same", 4, 6),
        task("other", 3, 0),
        task("same", 4, 6),
    ];
    let original = tasks.clone();
    let ranked = rank_tasks(&mut tasks);

    assert_eq!(
        ranked,
        vec![
            task("same", 4, 6),
            task("same", 4, 6),
            task("same", 4, 6),
            task("other", 3, 0),
        ]
    );
    assert_eq!(tasks, original);
}
"},{"id":"cap-v2-ordering_and_selection-rust-repair-02","test_code":"#[path = "solution.rs"]
mod solution;

use solution::select_label;

#[test]
fn selects_by_increasing_byte_length_then_lexicographically() {
    let mut labels = vec![
        "pear".to_string(),
        "a".to_string(),
        "fig".to_string(),
        "kiwi".to_string(),
        "be".to_string(),
        "apple".to_string(),
    ];
    let original = labels.clone();

    assert_eq!(select_label(&mut labels, 0), Some("a"));
    assert_eq!(select_label(&mut labels, 1), Some("be"));
    assert_eq!(select_label(&mut labels, 2), Some("fig"));
    assert_eq!(select_label(&mut labels, 3), Some("kiwi"));
    assert_eq!(select_label(&mut labels, 4), Some("pear"));
    assert_eq!(select_label(&mut labels, 5), Some("apple"));
    assert_eq!(labels, original);
}

#[test]
fn uses_utf8_byte_length_rather_than_character_count() {
    let mut labels = vec![
        "é".to_string(),
        "z".to_string(),
        "abc".to_string(),
        "界".to_string(),
    ];

    assert_eq!(select_label(&mut labels, 0), Some("z"));
    assert_eq!(select_label(&mut labels, 1), Some("é"));
    assert_eq!(select_label(&mut labels, 2), Some("abc"));
    assert_eq!(select_label(&mut labels, 3), Some("界"));
}

#[test]
fn identical_labels_tie_by_original_index() {
    let first = String::from("same");
    let second = String::from("same");
    let third = String::from("same");
    let first_ptr = first.as_ptr();
    let second_ptr = second.as_ptr();
    let third_ptr = third.as_ptr();
    let mut labels = vec![first, second, third];

    assert_eq!(select_label(&mut labels, 0).unwrap().as_ptr(), first_ptr);
    assert_eq!(select_label(&mut labels, 1).unwrap().as_ptr(), second_ptr);
    assert_eq!(select_label(&mut labels, 2).unwrap().as_ptr(), third_ptr);
}

#[test]
fn leaves_order_contents_and_allocations_unchanged_after_success() {
    let mut labels = vec![
        String::from("longest"),
        String::from("b"),
        String::from("aa"),
    ];
    let original = labels.clone();
    let original_ptrs: Vec<*const u8> = labels.iter().map(|label| label.as_ptr()).collect();
    let original_caps: Vec<usize> = labels.iter().map(String::capacity).collect();

    assert_eq!(select_label(&mut labels, 0), Some("b"));

    assert_eq!(labels, original);
    assert_eq!(
        labels.iter().map(|label| label.as_ptr()).collect::<Vec<_>>(),
        original_ptrs
    );
    assert_eq!(
        labels.iter().map(String::capacity).collect::<Vec<_>>(),
        original_caps
    );
}

#[test]
fn out_of_range_and_empty_selection_return_none_without_mutation() {
    let mut labels = vec!["bbb".to_string(), "a".to_string(), "cc".to_string()];
    let original = labels.clone();
    let original_ptrs: Vec<*const u8> = labels.iter().map(|label| label.as_ptr()).collect();
    let out_of_range = labels.len();

    assert_eq!(select_label(&mut labels, out_of_range), None);
    assert_eq!(labels, original);
    assert_eq!(
        labels.iter().map(|label| label.as_ptr()).collect::<Vec<_>>(),
        original_ptrs
    );

    let mut empty: Vec<String> = Vec::new();
    assert_eq!(select_label(&mut empty, 0), None);
}

#[test]
fn supports_empty_strings_as_valid_labels() {
    let mut labels = vec!["x".to_string(), "".to_string(), "aa".to_string()];
    let original = labels.clone();

    assert_eq!(select_label(&mut labels, 0), Some(""));
    assert_eq!(labels, original);
}
