mod solution;

use solution::{normalize_timeline, TimelineError};

#[test]
fn handles_empty_input_and_optional_final_lf() {
    assert_eq!(normalize_timeline(""), Ok(String::new()));
    assert_eq!(normalize_timeline("1\ta\tnote\n"), Ok("1\ta\tnote".to_owned()));
}

#[test]
fn sorts_ticks_and_canonicalizes_decimal_ticks() {
    let input = "10\tz\tten\n0002\tb\ttwo\n2\ta\tsecond";
    assert_eq!(
        normalize_timeline(input),
        Ok("2\tb\ttwo\n2\ta\tsecond\n10\tz\tten".to_owned())
    );
}

#[test]
fn equal_ticks_preserve_original_order_regardless_of_category() {
    let input = "7\tz\tfirst\n7\ta\tsecond\n7\tmiddle\tthird\n1\tx\tearlier\n7\ta\tfourth";
    assert_eq!(
        normalize_timeline(input),
        Ok("1\tx\tearlier\n7\tz\tfirst\n7\ta\tsecond\n7\tmiddle\tthird\n7\ta\tfourth".to_owned())
    );
}

#[test]
fn decodes_and_reencodes_note_escapes() {
    let input = "3\tevent\tline1\\nline2\\tpath\\\\file 世界";
    assert_eq!(normalize_timeline(input), Ok(input.to_owned()));
}

#[test]
fn accepts_tick_boundaries() {
    let input = "4294967295\tmax\tok\n0\tzero\tok";
    assert_eq!(
        normalize_timeline(input),
        Ok("0\tzero\tok\n4294967295\tmax\tok".to_owned())
    );
}

#[test]
fn accepts_valid_category_characters_and_empty_notes() {
    assert_eq!(
        normalize_timeline("3\ta_1\t\n2\tz9\tok"),
        Ok("2\tz9\tok\n3\ta_1\t".to_owned())
    );
}

#[test]
fn reports_wrong_field_count_with_one_based_line() {
    assert_eq!(
        normalize_timeline("1\ta\tok\n2\tonly_two"),
        Err(TimelineError::WrongFieldCount(2))
    );
    assert_eq!(
        normalize_timeline("1\ta\tx\textra"),
        Err(TimelineError::WrongFieldCount(1))
    );
}

#[test]
fn rejects_invalid_ticks() {
    assert_eq!(normalize_timeline("-1\ta\tx"), Err(TimelineError::InvalidTick(1)));
    assert_eq!(
        normalize_timeline("1\ta\tok\n4294967296\tb\tx"),
        Err(TimelineError::InvalidTick(2))
    );
    assert_eq!(normalize_timeline("\ta\tx"), Err(TimelineError::InvalidTick(1)));
}

#[test]
fn rejects_empty_or_malformed_categories() {
    assert_eq!(normalize_timeline("1\t\tx"), Err(TimelineError::InvalidCategory(1)));
    assert_eq!(normalize_timeline("1\tUpper\tx"), Err(TimelineError::InvalidCategory(1)));
    assert_eq!(
        normalize_timeline("1\tvalid\tx\n2\tbad-name\ty"),
        Err(TimelineError::InvalidCategory(2))
    );
    assert_eq!(
        normalize_timeline("1\tcafé\tx"),
        Err(TimelineError::InvalidCategory(1))
    );
}

#[test]
fn rejects_unknown_and_trailing_escapes() {
    assert_eq!(normalize_timeline("1\ta\tbad\\q"), Err(TimelineError::InvalidEscape(1)));
    assert_eq!(
        normalize_timeline("1\ta\tok\n2\tb\ttrailing\\"),
        Err(TimelineError::InvalidEscape(2))
    );
}

#[test]
fn an_extra_empty_record_is_not_ignored() {
    assert_eq!(
        normalize_timeline("1\ta\tok\n\n"),
        Err(TimelineError::WrongFieldCount(2))
    );
}

#[test]
fn normalization_does_not_mutate_owned_input() {
    let input = String::from("2\tb\tx\n1\ta\ty");
    let before = input.clone();
    assert_eq!(normalize_timeline(&input), Ok("1\ta\ty\n2\tb\tx".to_owned()));
    assert_eq!(input, before);
}
