    words.iter().map(|word| (*word).to_owned()).collect()
}

#[test]
fn empty_and_whitespace_only_inputs_produce_no_groups() {
    assert_eq!(group_words_by_length(""), Vec::<(usize, Vec<String>)>::new());
    assert_eq!(
        group_words_by_length(" \t\n\r\u{00a0}\u{2003}"),
