    );
}

#[test]
fn groups_preserve_first_length_order_and_word_order() {
    assert_eq!(
        group_words_by_length("one a two four bb six"),
        vec![
            (3, owned(&["one", "two", "six"])),
            (1, owned(&["a"])),
            (4, owned(&["four"])),
            (2, owned(&["bb"])),
        ]
    );
}

#[test]
fn duplicate_words_are_retained() {
    assert_eq!(
        group_words_by_length("go go stop go stop"),
        vec![
            (2, owned(&["go", "go", "go"])),
            (4, owned(&["stop", "stop"])),
