mod solution;

use solution::{rank_tasks, Task};

fn task(id: &str, priority: i32, deadline: u32) -> Task {
    Task {
        id: id.to_string(),
        priority,
        deadline,
    }
}

#[test]
fn ranks_by_priority_deadline_and_id() {
    let mut tasks = vec![
        task("zeta", 5, 2),
        task("beta", 7, 9),
        task("omega", 7, 1),
        task("alpha", 7, 1),
        task("low", -2, 0),
    ];

    assert_eq!(
        rank_tasks(&mut tasks),
        vec![
            task("alpha", 7, 1),
            task("omega", 7, 1),
            task("beta", 7, 9),
            task("zeta", 5, 2),
            task("low", -2, 0),
        ]
    );
}

#[test]
fn returns_independent_clones_and_leaves_input_unchanged() {
    let mut tasks = vec![
        task("last", 1, 9),
        task("first", 10, 1),
        task("middle", 5, 4),
    ];
    let original = tasks.clone();
    let task_addresses: Vec<*const Task> = tasks.iter().map(|item| item as *const Task).collect();
    let id_addresses: Vec<*const u8> = tasks.iter().map(|item| item.id.as_ptr()).collect();

    let ranked = rank_tasks(&mut tasks);

    assert_eq!(tasks, original);
    assert_eq!(
        tasks.iter().map(|item| item as *const Task).collect::<Vec<_>>(),
        task_addresses
    );
    assert_eq!(
        tasks.iter().map(|item| item.id.as_ptr()).collect::<Vec<_>>(),
        id_addresses
    );
    assert_eq!(
        ranked,
        vec![
            task("first", 10, 1),
            task("middle", 5, 4),
            task("last", 1, 9),
        ]
    );
    assert!(ranked
        .iter()
        .all(|copy| id_addresses.iter().all(|&address| copy.id.as_ptr() != address)));
}

#[test]
fn accepts_empty_and_single_element_slices() {
    let mut empty: Vec<Task> = Vec::new();
    assert!(rank_tasks(&mut empty).is_empty());

    let mut one = vec![task("only", 3, 8)];
    let original = one.clone();
    let original_id_address = one[0].id.as_ptr();
    let ranked = rank_tasks(&mut one);

    assert_eq!(ranked, original);
    assert_eq!(one, original);
    assert_eq!(one[0].id.as_ptr(), original_id_address);
    assert_ne!(ranked[0].id.as_ptr(), original_id_address);
}

#[test]
fn handles_numeric_boundaries_without_overflow() {
    let mut tasks = vec![
        task("minimum", i32::MIN, u32::MAX),
        task("maximum-late", i32::MAX, u32::MAX),
        task("maximum-early", i32::MAX, 0),
    ];
    let original = tasks.clone();

    assert_eq!(
        rank_tasks(&mut tasks),
        vec![
            task("maximum-early", i32::MAX, 0),
            task("maximum-late", i32::MAX, u32::MAX),
            task("minimum", i32::MIN, u32::MAX),
        ]
    );
    assert_eq!(tasks, original);
}

#[test]
fn preserves_multiplicity_for_tasks_equal_on_all_keys() {
