#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Task {
    pub id: String,
    pub priority: i32,
    pub deadline: u32,
}

pub fn rank_tasks(tasks: &mut [Task]) -> Vec<Task> {
    tasks.sort_by(|a, b| {
