Known-bad source:

```rust
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TimelineError {
    WrongFieldCount(usize),
    InvalidTick(usize),
    InvalidCategory(usize),
    InvalidEscape(usize),
}

#[derive(Debug, Clone)]
struct Entry {
    tick: u32,
    category: String,
    note: String,
}

fn decode_note(raw: &str, line: usize) -> Result<String, TimelineError> {
    let mut out = String::new();
    let mut chars = raw.chars();
    while let Some(ch) = chars.next() {
        if ch != '\\' {
            out.push(ch);
            continue;
        }
        match chars.next() {
            Some('\\') => out.push('\\'),
            Some('t') => out.push('\t'),
            Some('n') => out.push('\n'),
            _ => return Err(TimelineError::InvalidEscape(line)),
        }
    }
    Ok(out)
}

fn encode_note(note: &str) -> String {
    let mut out = String::new();
    for ch in note.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            _ => out.push(ch),
        }
    }
    out
}

pub fn normalize_timeline(input: &str) -> Result<String, TimelineError> {
    if input.is_empty() {
        return Ok(String::new());
    }
    let mut entries = Vec::new();
    for (index, record) in input.lines().enumerate() {
        let line = index + 1;
        let fields: Vec<&str> = record.split('\t').collect();
        if fields.len() != 3 {
            return Err(TimelineError::WrongFieldCount(line));
        }
        let tick = fields[0]
            .parse::<u32>()
            .map_err(|_| TimelineError::InvalidTick(line))?;
        if fields[1].is_empty()
            || !fields[1]
                .bytes()
                .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_')
        {
            return Err(TimelineError::InvalidCategory(line));
        }
        entries.push(Entry {
            tick,
            category: fields[1].to_owned(),
            note: decode_note(fields[2], line)?,
        });
    }
    entries.sort_by(|a, b| a.tick.cmp(&b.tick).then_with(|| a.category.cmp(&b.category)));
    Ok(entries
        .into_iter()
        .map(|entry| {
            format!(
                "{}\t{}\t{}",
                entry.tick,
                entry.category,
                encode_note(&entry.note)
            )
        })
        .collect::<Vec<_>>()
        .join("\n"))
}
