pub fn compact_fragments(fragments: &[&str]) -> Vec<String> {
    let mut output = Vec::with_capacity(fragments.len());
    let mut in_whitespace = false;

    for fragment in fragments {
        let mut compacted = String::new();
        for ch in fragment.chars() {
            if ch.is_whitespace() {
                if !in_whitespace {
                    compacted.push(' ');
                    in_whitespace = true;
                }
            } else {
                compacted.push(ch);
                in_whitespace = false;
            }
        }
        output.push(compacted);
    }

    output
}
