        (4, owned(&[\\\"four\\\"])),\\n            (2, owned(&[\\\"bb\\\"])),\\n        ]\\n    );\\n}\\n\\n#[test]\\nfn duplicate_words_are_retained() {\\n    assert_eq!(\\n        group_words_by_length(\\\"go go stop go stop\\\"),\\n        vec![\\n            (2, owned(&[\\\"go\\\", \\\"go\\\", \\\"go\\\"])),\\n            (4, owned(&[\\\"stop\\\", \\\"stop\\\"])),\\n        ]\\n    );\\n}\\n\\n#[test]\\nfn lengths_count_unicode_scalars_instead_of_utf8_bytes() {\\n    assert_eq!(\\n        group_words_by_length(\\\"é 🦀 e\\\\u{0301} 東京 🚀🚀\\\"),\\n        vec![\\n            (1, owned(&[\\\"é\\\", \\\"🦀\\\"])),\\n            (2, owned(&[\\\"e\\\\u{0301}\\\", \\\"東京\\\", \\\"🚀🚀\\\"])),\\n        ]\\n    );\\n}\\n\\n#[test]\\nfn every_unicode_whitespace_separator_splits_words() {\\n    assert_eq!(\\n        group_words_by_length(\\\"a\\\\u{00a0}\\\\u{00a0}bb\\\\u{2003}c\\\\tdd\\\\n大\\\"),\\n        vec![\\n            (1, owned(&[\\\"a\\\", \\\"c\\\", \\\"大\\\"])),\\n            (2, owned(&[\\\"bb\\\", \\\"dd\\\"])),\\n        ]\\n    );\\n}\\n\\n#[test]\\nfn leading_trailing_and_consecutive_separators_create_no_empty_words() {\\n    assert_eq!(\\n        group_words_by_length(\\\"  alpha\\\\n\\\\nβ  \\\"),\\n        vec![(5, owned(&[\\\"alpha\\\"])), (1, owned(&[\\\"β\\\"]))]\\n    );\\n}\\n\"},{\"id\":\"cap-v2-string_and_unicode-rust-repair-01\",\"test_code\":\"#[path = \\\"solution.rs\\\"]\\nmod solution;\\n\\nuse solution::compact_fragments;\\n\\nfn strings(values: &[&str]) -> Vec<String> {\\n    values.iter().map(|value| (*value).to_owned()).collect()\\n}\\n\\n#[test]\\nfn empty_input_and_empty_fragments_are_preserved() {\\n    assert_eq!(compact_fragments(&[]), Vec::<String>::new());\\n    assert_eq!(compact_fragments(&[\\\"\\\", \\\"\\\", \\\"\\\"]), strings(&[\\\"\\\", \\\"\\\", \\\"\\\"]));\\n}\\n\\n#[test]\\nfn compacts_each_maximal_whitespace_run_to_one_ascii_space() {\\n    assert_eq!(\\n        compact_fragments(&[\\\"alpha \\\\t\\\\n beta\\\", \\\"x\\\\u{00a0}\\\\u{2003}y\\\"]),\\n        strings(&[\\\"alpha beta\\\", \\\"x y\\\"])\\n    );\\n}\\n\\n#[test]\\nfn retains_leading_and_trailing_compacted_spaces() {\\n    assert_eq!(\\n        compact_fragments(&[\\\" \\\\talpha\\\\n\\\", \\\"\\\\u{00a0}\\\", \\\"beta  \\\"]),\\n        strings(&[\\\" alpha \\\", \\\" \\\", \\\"beta \\\"])\\n    );\\n}\\n\\n#[test]\\nfn whitespace_state_resets_after_fragment_ending_in_whitespace() {\\n    assert_eq!(\\n        compact_fragments(&[\\\"first   \\\", \\\"\\\\t\\\\nsecond\\\", \\\"\\\\u{00a0}third\\\"]),\\n        strings(&[\\\"first \\\", \\\" second\\\", \\\" third\\\"])\\n    );\\n}\\n\\n#[test]\\nfn empty_fragment_does_not_carry_whitespace_state_to_next_fragment() {\\n    assert_eq!(\\n        compact_fragments(&[\\\"ends \\\", \\\"\\\", \\\" starts\\\"]),\\n        strings(&[\\\"ends \\\", \\\"\\\", \\\" starts\\\"])\\n    );\\n}\\n\\n#[test]\\nfn non_whitespace_unicode_scalars_are_copied_unchanged() {\\n    assert_eq!(\\n        compact_fragments(&[\\\"é🦀東京\\\", \\\"a\\\\u{0301}  ß\\\"]),\\n        strings(&[\\\"é🦀東京\\\", \\\"a\\\\u{0301} ß\\\"])\\n    );\\n}\\n\\n#[test]\\nfn source_fragments_are_not_mutated() {\\n    let fragments = [\\\"a  b\\\", \\\" c\\\\t\\\"];\\n    let before = fragments;\\n\\n    let result = compact_fragments(&fragments);\\n\\n    assert_eq!(result, strings(&[\\\"a b\\\", \\\" c \\\"]));\\n    assert_eq!(fragments, before);\\n}\\n\"},{\"id\":\"cap-v2-string_and_unicode-rust-repair-02\",\"test_code\":\"#[path = \\\"solution.rs\\\"]\\nmod solution;\\n\\nuse solution::titlecase_records;\\n\\nfn strings(values: &[&str]) -> Vec<String> {\\n    values.iter().map(|value| (*value).to_owned()).collect()\\n}\\n\\n#[test]\\nfn empty_input_and_empty_records_are_preserved() {\\n    assert_eq!(titlecase_records(&[]), Vec::<String>::new());\\n    assert_eq!(titlecase_records(&[\\\"\\\", \\\"\\\"]), strings(&[\\\"\\\", \\\"\\\"]));\\n}\\n\\n#[test]\\nfn titlecases_each_whitespace_delimited_word_without_lowercasing_the_rest() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"hello world\\\", \\\"hELLO wORLD\\\"]),\\n        strings(&[\\\"Hello World\\\", \\\"HELLO WORLD\\\"])\\n    );\\n}\\n\\n#[test]\\nfn preserves_unicode_whitespace_exactly() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"alpha\\\\tbeta\\\\nγamma\\\\u{00a0}delta\\\\u{2003}echo\\\"]),\\n        strings(&[\\\"Alpha\\\\tBeta\\\\nΓamma\\\\u{00a0}Delta\\\\u{2003}Echo\\\"])\\n    );\\n}\\n\\n#[test]\\nfn uses_complete_uppercase_expansion_at_word_start() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"ßeta straße\\\", \\\"ﬃle\\\"]),\\n        strings(&[\\\"SSeta Straße\\\", \\\"FFIle\\\"])\\n    );\\n}\\n\\n#[test]\\nfn word_start_state_resets_for_every_record() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"alpha\\\", \\\"beta\\\", \\\"γamma\\\"]),\\n        strings(&[\\\"Alpha\\\", \\\"Beta\\\", \\\"Γamma\\\"])\\n    );\\n}\\n\\n#[test]\\nfn empty_record_does_not_prevent_next_record_from_starting_a_word() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"first\\\", \\\"\\\", \\\"second\\\"]),\\n        strings(&[\\\"First\\\", \\\"\\\", \\\"Second\\\"])\\n    );\\n}\\n\\n#[test]\\nfn leading_and_trailing_whitespace_are_retained() {\\n    assert_eq!(\\n        titlecase_records(&[\\\"  alpha\\\\t\\\", \\\"\\\\nßeta\\\\u{00a0}\\\"]),\\n        strings(&[\\\"  Alpha\\\\t\\\", \\\"\\\\nSSeta\\\\u{00a0}\\\"])\\n    );\\n}\\n\\n#[test]\\nfn source_records_are_not_mutated() {\\n    let records = [\\\"alpha beta\\\", \\\"ßeta\\\"];\\n    let before = records;\\n\\n    let result = titlecase_records(&records);\\n\\n    assert_eq!(result, strings(&[\\\"Alpha Beta\\\", \\\"SSeta\\\"]));\\n    assert_eq!(records, before);\\n}\\n\"}]}"}}
