{"items":[{"id":"cap-v2-callbacks_and_events-typescript-repair-02","test_code":"import { AcknowledgedBroadcaster } from "./solution";
import type { Broadcast } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equalStrings(
  actual: readonly string[],
  expected: readonly string[],
  message: string,
): void {
  assert(actual.length === expected.length, message + " (length)");
  for (let index = 0; index < expected.length; index++) {
    assert(actual[index] === expected[index], message + " (index " + index + ")");
  }
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  const callerLabels = ["one", "two"];
  const callerMessage: Broadcast = { channel: "news", labels: callerLabels };
  const events: string[] = [];
  const received: Broadcast[] = [];
  let completionCount = 0;

  broadcaster.subscribe((message, acknowledge) => {
    received.push(message);
    events.push("first");
    (message as { channel: string }).channel = "changed";
    (message.labels as string[]).push("private");
    acknowledge();
  });
  broadcaster.subscribe((message, acknowledge) => {
    received.push(message);
    events.push(message.channel);
    equalStrings(message.labels, ["one", "two"], "listener labels must be isolated");
    acknowledge();
  });

  broadcaster.publish(callerMessage, (error) => {
    completionCount++;
    assert(error === null, "successful publication must report null");
  });

  assert(completionCount === 1, "publication must complete exactly once");
  equalStrings(events, ["first", "news"], "listeners must run in registration order");
  assert(received.length === 2, "both listeners must receive a message");
  assert(received[0] !== received[1], "each listener must receive its own object");
  assert(received[0].labels !== received[1].labels, "each listener must receive its own labels array");
  assert(callerMessage.channel === "news", "listener mutation must not change the caller message");
  equalStrings(callerLabels, ["one", "two"], "listener mutation must not change caller labels");
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  const events: string[] = [];
  let unsubscribeSecond: () => void = () => undefined;

  broadcaster.subscribe((_message, acknowledge) => {
    events.push("first");
    unsubscribeSecond();
    broadcaster.subscribe((_laterMessage, laterAcknowledge) => {
      events.push("late");
      laterAcknowledge();
    });
    acknowledge();
  });
  unsubscribeSecond = broadcaster.subscribe((_message, acknowledge) => {
    events.push("second");
    acknowledge();
  });

  broadcaster.publish({ channel: "snapshot", labels: [] }, (error) => {
    assert(error === null, "captured publication must succeed");
    events.push("complete-first");
  });
  equalStrings(
    events,
    ["first", "second", "complete-first"],
    "subscription changes must not affect an active publication",
  );

  events.length = 0;
  broadcaster.publish({ channel: "next", labels: [] }, (error) => {
    assert(error === null, "later publication must succeed");
    events.push("complete-next");
  });
  equalStrings(
    events,
    ["first", "late", "complete-next"],
    "later publications must use the updated registrations",
  );
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  let firstCount = 0;
  let secondCount = 0;
  const unsubscribeFirst = broadcaster.subscribe((_message, acknowledge) => {
    firstCount++;
    acknowledge();
  });
  const unsubscribeSecond = broadcaster.subscribe((_message, acknowledge) => {
    secondCount++;
    acknowledge();
  });

  unsubscribeFirst();
  unsubscribeFirst();
  broadcaster.publish({ channel: "remaining", labels: [] }, (error) => {
    assert(error === null, "remaining registration must succeed");
  });
  assert(firstCount === 0 && secondCount === 1, "unsubscribe must be independent and idempotent");

  unsubscribeSecond();
  let emptyCompletionCount = 0;
  broadcaster.publish({ channel: "empty", labels: [] }, (error) => {
    emptyCompletionCount++;
    assert(error === null, "publication with no registrations must succeed");
  });
  assert(emptyCompletionCount === 1, "publication with no registrations must complete immediately once");
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  const acknowledgements: Array<(error?: Error) => void> = [];
  const firstFailure = new Error("first failure");
  let completionCount = 0;
  let result: Error | null | undefined;

  broadcaster.subscribe((_message, acknowledge) => {
    acknowledgements.push(acknowledge);
  });
  broadcaster.subscribe((_message, acknowledge) => {
    acknowledgements.push(acknowledge);
  });
  broadcaster.subscribe(() => {
    throw "third failure";
  });

  broadcaster.publish({ channel: "errors", labels: [] }, (error) => {
    completionCount++;
    result = error;
  });

  assert(acknowledgements.length === 2, "pending acknowledgements must be captured");
  assert(completionCount === 0, "publication must wait for every captured listener");
  acknowledgements[1]();
  acknowledgements[1](new Error("ignored repeat"));
  assert(completionCount === 0, "a repeated acknowledgement must not settle another listener");
  acknowledgements[0](firstFailure);
  assert(completionCount === 1, "publication must complete after all listeners settle");
  assert(result === firstFailure, "the earliest registered failure must win");
  acknowledgements[0]();
  assert(completionCount === 1, "repeated acknowledgement must not repeat completion");
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  let result: Error | null | undefined;
  broadcaster.subscribe((_message, acknowledge) => {
    acknowledge();
    throw new Error("ignored after acknowledgement");
  });
  broadcaster.publish({ channel: "post-ack", labels: [] }, (error) => {
    result = error;
  });
  assert(result === null, "a throw after acknowledgement must be ignored");
}

{
  const broadcaster = new AcknowledgedBroadcaster();
  let result: Error | null | undefined;
  broadcaster.subscribe(() => {
    throw 17;
  });
  broadcaster.publish({ channel: "throw", labels: [] }, (error) => {
    result = error;
  });
  assert(result instanceof Error, "a non-Error throw must be converted");
  assert(result.message === "17", "a converted throw must use String(value)");
}
"},{"id":"cap-v2-numeric_reasoning-typescript-generation-02","test_code":"import { createRollingAverage } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, received ${String(actual)}`);
  }
}

function assertClose(actual: number, expected: number, message: string): void {
  const tolerance = Number.EPSILON * Math.max(1, Math.abs(actual), Math.abs(expected)) * 8;
  if (Math.abs(actual - expected) > tolerance) {
    throw new Error(`${message}: expected ${expected}, received ${actual}`);
  }
}

function assertRangeError(action: () => unknown, message: string): void {
  let thrown: unknown;
  try {
    action();
  } catch (error) {
    thrown = error;
  }
  assert(thrown instanceof RangeError, `${message}: expected RangeError`);
}

for (const invalidWidth of [
  0,
  -1,
  1.5,
  Number.NaN,
  Number.POSITIVE_INFINITY,
  Number.NEGATIVE_INFINITY,
]) {
  assertRangeError(
    () => createRollingAverage(invalidWidth),
    `invalid width ${String(invalidWidth)}`,
  );
}

{
  const average = createRollingAverage(3);
  assertEqual(average.mean(), undefined, "mean is undefined before the first push");
  assertEqual(average.count(), 0, "a new window is empty");
  assertEqual(average.push(2), 2, "first push mean");
  assertEqual(average.count(), 1, "count after first push");
  assertEqual(average.push(4), 3, "second push mean");
  assertEqual(average.push(9), 5, "full-window mean");
  assertEqual(average.count(), 3, "count is capped at width");
  assertClose(average.push(15), 28 / 3, "the oldest sample is evicted");
  assertEqual(average.count(), 3, "count remains capped after eviction");
  assertClose(average.mean() as number, 28 / 3, "mean matches the latest push result");
  assertClose(average.push(-3), 7, "negative finite values are accepted");
}

{
  const fractional = createRollingAverage(2);
  assertClose(fractional.push(0.1), 0.1, "fractional first value");
  assertClose(fractional.push(0.2), 0.15, "fractional mean");
  assertClose(fractional.push(0.3), 0.25, "fractional eviction mean");
  assertClose(fractional.mean() as number, 0.25, "fractional stored mean");
}

{
  const single = createRollingAverage(1);
  assert(single.push(-0) === 0, "negative zero is a valid finite sample");
  assertEqual(single.count(), 1, "width-one count");
  assertEqual(single.push(8), 8, "width one retains only the newest value");
  assertEqual(single.mean(), 8, "width-one mean");
}

{
  const stable = createRollingAverage(2);
  stable.push(10);
  for (const invalidValue of [
    Number.NaN,
    Number.POSITIVE_INFINITY,
    Number.NEGATIVE_INFINITY,
  ]) {
    assertRangeError(() => stable.push(invalidValue), `push rejects ${String(invalidValue)}`);
    assertEqual(stable.count(), 1, "a failed push preserves count");
    assertEqual(stable.mean(), 10, "a failed push preserves mean");
  }
}

{
  const first = createRollingAverage(2);
  const second = createRollingAverage(2);
  first.push(1);
  first.push(3);
  first.push(5);
  assertEqual(second.count(), 0, "a second instance is unaffected by the first");
  assertEqual(second.mean(), undefined, "the second instance remains empty");
  assertEqual(second.push(20), 20, "the second instance accepts its own sample");
  assertEqual(first.mean(), 4, "the first instance retains its own window");
}

{
  const veryWide = createRollingAverage(Number.MAX_SAFE_INTEGER);
  assertEqual(veryWide.push(6), 6, "a large positive integer width is supported");
  assertEqual(veryWide.count(), 1, "large-width window count");
}
"},{"id":"cap-v2-ordering_and_selection-typescript-repair-01","test_code":"import { chooseDispatchOffer } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function assertJsonEqual(actual: unknown, expected: unknown, message: string): void {
  const actualJson = JSON.stringify(actual);
  const expectedJson = JSON.stringify(expected);
  if (actualJson !== expectedJson) {
    throw new Error(`${message}: expected ${expectedJson}, got ${actualJson}`);
  }
}

assertEqual(chooseDispatchOffer(null), null, "null input is not an array");
assertEqual(chooseDispatchOffer({}), null, "object input is not an array");
assertEqual(chooseDispatchOffer("offers"), null, "string input is not an array");
assertEqual(chooseDispatchOffer([]), null, "an empty array has no valid offers");

const malformed: unknown[] = [
  null,
  [],
  "text",
  {},
  { offerId: "", carrier: "Carrier", etaMinutes: 1, costCredits: 1 },
  { offerId: " \t\n ", carrier: "Carrier", etaMinutes: 1, costCredits: 1 },
  { offerId: "id", carrier: "   ", etaMinutes: 1, costCredits: 1 },
  { offerId: "id", carrier: "Carrier", etaMinutes: -1, costCredits: 1 },
  { offerId: "id", carrier: "Carrier", etaMinutes: 1.5, costCredits: 1 },
  { offerId: "id", carrier: "Carrier", etaMinutes: Number.NaN, costCredits: 1 },
  { offerId: "id", carrier: "Carrier", etaMinutes: Number.POSITIVE_INFINITY, costCredits: 1 },
  { offerId: "id", carrier: "Carrier", etaMinutes: 1, costCredits: -1 },
  { offerId: "id", carrier: "Carrier", etaMinutes: 1, costCredits: Number.NaN },
  { offerId: "id", carrier: "Carrier", etaMinutes: 1, costCredits: Number.POSITIVE_INFINITY },
  { offerId: "id", carrier: "Carrier", etaMinutes: 1, costCredits: Number.NEGATIVE_INFINITY },
  { offerId: 12, carrier: "Carrier", etaMinutes: 1, costCredits: 1 },
  { offerId: "id", carrier: 12, etaMinutes: 1, costCredits: 1 },
];
assertEqual(
  chooseDispatchOffer(malformed),
  null,
  "all malformed entries must be ignored",
);

const offers = [
  { offerId: "cheap-but-slow", carrier: "A", etaMinutes: 11, costCredits: 0 },
  { offerId: "expensive", carrier: "A", etaMinutes: 10, costCredits: 5 },
  { offerId: "carrier-z", carrier: "Z", etaMinutes: 10, costCredits: 4 },
  { offerId: "id-z", carrier: "A", etaMinutes: 10, costCredits: 4 },
  { offerId: "id-A", carrier: "A", etaMinutes: 10, costCredits: 4, ignored: "extra" },
  { offerId: "invalid", carrier: "A", etaMinutes: 0, costCredits: Infinity },
];
const before = JSON.stringify(offers);
const result = chooseDispatchOffer(offers);
assertJsonEqual(
  result,
  { offerId: "id-A", carrier: "A", etaMinutes: 10, costCredits: 4 },
  "selection must apply eta, cost, carrier, and offerId tie breakers",
);
assert(result !== null, "a valid offer must be selected");
assert(result !== offers[4], "the selected offer must be newly allocated");
assertJsonEqual(
  Object.keys(result).sort(),
  ["carrier", "costCredits", "etaMinutes", "offerId"],
  "the result must contain only the exported fields",
);
result.carrier = "Changed";
assertEqual(offers[4].carrier, "A", "mutating the result must not affect the input");
assertEqual(JSON.stringify(offers), before, "the function must not mutate its input");

const boundary = chooseDispatchOffer([
  { offerId: "zero", carrier: "C", etaMinutes: 0, costCredits: 0 },
]);
assertJsonEqual(
  boundary,
  { offerId: "zero", carrier: "C", etaMinutes: 0, costCredits: 0 },
  "zero eta and zero cost are valid",
);

const spaced = chooseDispatchOffer([
  { offerId: " id ", carrier: " carrier ", etaMinutes: 2, costCredits: -0 },
]);
assertJsonEqual(
  spaced,
  { offerId: " id ", carrier: " carrier ", etaMinutes: 2, costCredits: -0 },
  "valid strings are preserved rather than trimmed",
);

const utf16 = chooseDispatchOffer([
  { offerId: "private", carrier: "\uE000", etaMinutes: 1, costCredits: 1 },
  { offerId: "emoji", carrier: "😀", etaMinutes: 1, costCredits: 1 },
]);
assertEqual(
  utf16 === null ? "" : utf16.offerId,
  "emoji",
  "carrier comparison must use UTF-16 code-unit order",
);

const duplicateValues = [
  { offerId: "same", carrier: "C", etaMinutes: 3, costCredits: 2 },
  { offerId: "same", carrier: "C", etaMinutes: 3, costCredits: 2 },
];
const duplicateResult = chooseDispatchOffer(duplicateValues);
assertJsonEqual(
  duplicateResult,
  duplicateValues[0],
  "fully tied valid offers must produce the shared field values",
);
assert(duplicateResult !== duplicateValues[0] && duplicateResult !== duplicateValues[1], "a fully tied result must still be newly allocated");
"},{"id":"cap-v2-stateful_workflows-typescript-generation-01","test_code":"import { ParcelWorkflow } from "./solution";
import type { ParcelView } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function assertView(actual: ParcelView, expected: ParcelView, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function expectError(expected: string, action: () => unknown): void {
  let thrown: unknown;
  try {
    action();
  } catch (error) {
    thrown = error;
  }
  assert(thrown instanceof Error, `expected Error: ${expected}`);
  assert(thrown.message === expected, `expected error "${expected}", got "${thrown.message}"`);
}

const workflow = new ParcelWorkflow();
assertView(
  workflow.view(),
  { state: "EMPTY", parcelCode: null, weightGrams: null },
  "a new workflow must be empty",
);

expectError("command must be an object", () => workflow.apply(null));
expectError("command must be an object", () => workflow.apply([]));
expectError("command must be an object", () => workflow.apply("PACK"));
expectError("command must be an object", () => workflow.apply(3));
expectError("type must be PACK, DISPATCH, DELIVER, or RESET", () => workflow.apply({}));
expectError("type must be PACK, DISPATCH, DELIVER, or RESET", () => workflow.apply({ type: "START" }));
expectError("type must be PACK, DISPATCH, DELIVER, or RESET", () => workflow.apply({ type: 1 }));
expectError("PACK.parcelCode must be a non-empty string", () =>
  workflow.apply({ type: "PACK", parcelCode: "   ", weightGrams: 1 }),
);
expectError("PACK.parcelCode must be a non-empty string", () =>
  workflow.apply({ type: "PACK", parcelCode: 7, weightGrams: 1 }),
);
expectError("PACK.weightGrams must be a positive integer", () =>
  workflow.apply({ type: "PACK", parcelCode: "P", weightGrams: 0 }),
);
expectError("PACK.weightGrams must be a positive integer", () =>
  workflow.apply({ type: "PACK", parcelCode: "P", weightGrams: -1 }),
);
expectError("PACK.weightGrams must be a positive integer", () =>
  workflow.apply({ type: "PACK", parcelCode: "P", weightGrams: 1.5 }),
);
expectError("PACK.weightGrams must be a positive integer", () =>
  workflow.apply({ type: "PACK", parcelCode: "P", weightGrams: Number.POSITIVE_INFINITY }),
);
assertView(
  workflow.view(),
  { state: "EMPTY", parcelCode: null, weightGrams: null },
  "malformed commands must not change the workflow",
);

assertView(
  workflow.apply({ type: "PACK", parcelCode: " P-1 ", weightGrams: 1, ignored: true }),
  { state: "PACKED", parcelCode: " P-1 ", weightGrams: 1 },
  "PACK must store valid parcel data and allow additional properties",
);

expectError("PACK.weightGrams must be a positive integer", () =>
  workflow.apply({ type: "PACK", parcelCode: "other", weightGrams: 0 }),
);
assertView(
  workflow.view(),
  { state: "PACKED", parcelCode: " P-1 ", weightGrams: 1 },
  "field validation must occur before transition validation",
);
expectError("invalid transition: PACKED -> PACK", () =>
  workflow.apply({ type: "PACK", parcelCode: "other", weightGrams: 2 }),
);
expectError("invalid transition: PACKED -> DELIVER", () => workflow.apply({ type: "DELIVER" }));
assertView(
  workflow.view(),
  { state: "PACKED", parcelCode: " P-1 ", weightGrams: 1 },
  "invalid transitions must preserve parcel data",
);

assertView(
  workflow.apply({ type: "DISPATCH", extra: "ignored" }),
  { state: "DISPATCHED", parcelCode: " P-1 ", weightGrams: 1 },
  "DISPATCH must retain parcel data",
);
expectError("invalid transition: DISPATCHED -> RESET", () => workflow.apply({ type: "RESET" }));
assertView(
  workflow.apply({ type: "DELIVER" }),
  { state: "DELIVERED", parcelCode: " P-1 ", weightGrams: 1 },
  "DELIVER must reach the delivered state",
);
expectError("invalid transition: DELIVERED -> DISPATCH", () => workflow.apply({ type: "DISPATCH" }));
assertView(
  workflow.apply({ type: "RESET" }),
  { state: "EMPTY", parcelCode: null, weightGrams: null },
  "RESET must clear delivered parcel data",
);
expectError("invalid transition: EMPTY -> RESET", () => workflow.apply({ type: "RESET" }));
assertView(
  workflow.view(),
  { state: "EMPTY", parcelCode: null, weightGrams: null },
  "a failed RESET must leave the workflow empty",
);
"},{"id":"cap-v2-stateful_workflows-typescript-generation-02","test_code":"import { ReviewCycle } from "./solution";
import type { ReviewView } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
