"},{"id":"cap-v2-stateful_workflows-typescript-repair-01","test_code":"import { TaskScheduler } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function expectError(expected: string, action: () => unknown): void {
  let thrown: unknown;
  try {
    action();
  } catch (error) {
    thrown = error;
  }
  assert(thrown instanceof Error, `expected Error: ${expected}`);
  assert(thrown.message === expected, `expected error "${expected}", got "${thrown.message}"`);
}

{
  const empty = new TaskScheduler();
  assert(empty.startNext() === undefined, "startNext must return undefined when no tasks exist");
  assert(empty.getState("missing") === undefined, "an unknown task must have no state");
  expectError("Task is not running: missing", () => empty.complete("missing"));
  assert(empty.startNext() === undefined, "failed completion must not create a task");
}

{
  const scheduler = new TaskScheduler();
  scheduler.enqueue("low", -5);
  scheduler.enqueue("z-first-tie", 10);
  scheduler.enqueue("highest", 20);
  scheduler.enqueue("a-second-tie", 10);
  scheduler.enqueue("zero", 0);

  assert(scheduler.getState("low") === "QUEUED", "enqueue must create a queued task");
  assert(scheduler.getState("highest") === "QUEUED", "every enqueued task must begin queued");
  assert(scheduler.startNext() === "highest", "the greatest priority must start first");
  assert(scheduler.getState("highest") === "RUNNING", "the selected task must become running");

  expectError("Task is not running: low", () => scheduler.complete("low"));
  assert(scheduler.getState("low") === "QUEUED", "failed completion must preserve a queued task");
  assert(scheduler.getState("highest") === "RUNNING", "failed completion must not affect another task");

  scheduler.complete("highest");
  assert(scheduler.getState("highest") === "COMPLETED", "a completed running task must be marked completed");
  expectError("Task is not running: highest", () => scheduler.complete("highest"));
  assert(scheduler.getState("highest") === "COMPLETED", "re-completing a task must preserve its state");

  assert(
    scheduler.startNext() === "z-first-tie",
    "equal priorities must use original enqueue order rather than lexical ID order",
  );
  assert(scheduler.getState("z-first-tie") === "RUNNING", "the first tied task must become running");
  scheduler.complete("z-first-tie");

  assert(
    scheduler.startNext() === "a-second-tie",
    "earlier completions must not change enqueue ordering among remaining ties",
  );
  assert(scheduler.startNext() === "zero", "the next greatest remaining priority must be selected");
  assert(scheduler.startNext() === "low", "negative finite priorities must be ranked correctly");
  assert(scheduler.startNext() === undefined, "nothing is returned when no queued tasks remain");
  assert(scheduler.getState("a-second-tie") === "RUNNING", "starting another task must not alter running tasks");
  assert(scheduler.getState("zero") === "RUNNING", "multiple tasks may remain running independently");
  assert(scheduler.getState("low") === "RUNNING", "the final selected task must become running");
}

{
  const boundary = new TaskScheduler();
  boundary.enqueue("first", 1);
  boundary.enqueue("second", 1);
  boundary.enqueue("third", 1);
  assert(boundary.startNext() === "first", "the earliest equal-priority task must win");
  boundary.complete("first");
  assert(boundary.startNext() === "second", "the next tie must retain its original enqueue order");
  assert(boundary.startNext() === "third", "the last tie must retain its original enqueue order");
  assert(boundary.startNext() === undefined, "running tasks are not eligible to start again");
}

{
  const extremes = new TaskScheduler();
  extremes.enqueue("minimum", -Number.MAX_VALUE);
  extremes.enqueue("maximum", Number.MAX_VALUE);
  assert(extremes.startNext() === "maximum", "large finite priorities must be ordered correctly");
  assert(extremes.startNext() === "minimum", "a large negative finite priority remains eligible");
}
