{
  const broadcaster = new AcknowledgedBroadcaster();
  const callerLabels = ["one", "two"];
  const callerMessage: Broadcast = { channel: "news", labels: callerLabels };
  const events: string[] = [];
  const received: Broadcast[] = [];
  let completionCount = 0;

  broadcaster.subscribe((message, acknowledge) => {
    received.push(message);
    events.push("first");
    (message as { channel: string }).channel = "changed";
    (message.labels as string[]).push("private");
    acknowledge();
  });
  broadcaster.subscribe((message, acknowledge) => {
    received.push(message);
    events.push(message.channel);
    equalStrings(message.labels, ["one", "two"], "listener labels must be isolated");
    acknowledge();
  });

  broadcaster.publish(callerMessage, (error) => {
    completionCount++;
    assert(error === null, "successful publication must report null");
  });

  assert(completionCount === 1, "publication must complete exactly once");
  equalStrings(events, ["first", "news"], "listeners must run in registration order");
  assert(received.length === 2, "both listeners must receive a message");
  assert(received[0] !== received[1], "each listener must receive its own object");
  assert(received[0].labels !== received[1].labels, "each listener must receive its own labels array");
  assert(callerMessage.channel === "news", "listener mutation must not change the caller message");
