`chooseDispatchOffer` receives an unknown value. If it is not an array, return `null`. Ignore every array element that is not an object having all of these valid fields:

- `offerId`: a string containing at least one non-whitespace character
- `carrier`: a string containing at least one non-whitespace character
- `etaMinutes`: a nonnegative integer
- `costCredits`: a nonnegative finite number

Among valid offers, select the one with lower `etaMinutes`, then lower `costCredits`, then lexicographically smaller `carrier`, then lexicographically smaller `offerId`, and finally earlier input position. String comparisons use UTF-16 code-unit order. Return a newly allocated object containing only the four exported fields, or `null` if no valid offer exists.

Use only standard language and runtime APIs. Do not access the filesystem, network, clock, or randomness.

```ts
export interface DispatchOffer {
  offerId: string;
  carrier: string;
  etaMinutes: number;
  costCredits: number;
}

interface IndexedOffer {
  offer: DispatchOffer;
  index: number;
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function readOffer(value: unknown): DispatchOffer | null {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return null;
  }

  const record = value as Record<string, unknown>;
  if (
    typeof record.offerId !== "string" ||
    record.offerId.trim().length === 0 ||
    typeof record.carrier !== "string" ||
    record.carrier.trim().length === 0 ||
    !Number.isInteger(record.etaMinutes) ||
    (record.etaMinutes as number) < 0 ||
    typeof record.costCredits !== "number" ||
    record.costCredits < 0
  ) {
    return null;
  }

  return {
    offerId: record.offerId,
    carrier: record.carrier,
    etaMinutes: record.etaMinutes as number,
    costCredits: record.costCredits,
  };
}

function compareOffers(left: IndexedOffer, right: IndexedOffer): number {
  if (left.offer.etaMinutes !== right.offer.etaMinutes) {
    return left.offer.etaMinutes - right.offer.etaMinutes;
  }
  if (left.offer.costCredits !== right.offer.costCredits) {
    return left.offer.costCredits - right.offer.costCredits;
  }
  const byCarrier = compareText(left.offer.carrier, right.offer.carrier);
  if (byCarrier !== 0) {
    return byCarrier;
  }
  const byId = compareText(left.offer.offerId, right.offer.offerId);
  return byId !== 0 ? byId : left.index - right.index;
}

export function chooseDispatchOffer(input: unknown): DispatchOffer | null {
  if (!Array.isArray(input)) {
    return null;
  }

  let best: IndexedOffer | null = null;
  input.forEach((value, index) => {
    const offer = readOffer(value);
    if (offer === null) {
      return;
    }
    const candidate: IndexedOffer = { offer, index };
    if (best === null || compareOffers(candidate, best) < 0) {
      best = candidate;
    }
  });

  return best === null ? null : { ...best.offer };
}
